import { parseArgs, CliExit } from "./lib/cli.mjs";
import { convertbits, decode, encode } from "./lib/bech32.mjs";
import { formatPythonList } from "./lib/format.mjs";

function basename(filePath) {
  const normalized = String(filePath).replace(/\\/g, "/");
  const parts = normalized.split("/");
  return parts[parts.length - 1] || "test16.mjs";
}

function parsePythonInt(raw) {
  const normalized = String(raw).trim();
  if (!/^[+-]?\d+$/.test(normalized)) {
    throw new Error(`invalid literal for int() with base 10: '${raw}'`);
  }
  return Number.parseInt(normalized, 10);
}

function parseWitnessProgram(raw) {
  return raw.split(",").map((value) => parsePythonInt(value));
}

function writeLine(text) {
  process.stdout.write(`${text}\n`);
}

export function main(argv = process.argv.slice(2), progName = basename(process.argv[1])) {
  const args = parseArgs(argv, progName);
  const data = parseWitnessProgram(args.c);

  const converted = convertbits(data, 8, 5);
  const encoded = encode(args.a, args.b, converted);
  const decoded = decode(args.a, encoded);

  if (decoded[0] !== null && decoded[1] !== null) {
    const witnessVersion = decoded[0];
    const witnessProgram = decoded[1];
    const convertedBack = convertbits(witnessProgram, 5, 8);

    writeLine(formatPythonList(converted));
    writeLine(encoded);
    writeLine(String(witnessVersion));
    writeLine(formatPythonList(convertedBack));
  }
}

try {
  main();
} catch (error) {
  if (error instanceof CliExit) {
    const output = error.output;
    if (error.stream === "stdout") {
      process.stdout.write(output);
    } else {
      process.stderr.write(output);
    }
    process.exit(error.code);
  }

  throw error;
}

