import { bech32Decode, bech32Encode } from "./bech32_core.mjs";

export function convertbits(data, frombits, tobits, pad = true) {
  let accumulator = 0;
  let bits = 0;
  const result = [];
  const maxValue = (1 << tobits) - 1;
  const maxAccumulator = (1 << (frombits + tobits - 1)) - 1;

  for (const value of data) {
    if (value < 0 || (value >> frombits) !== 0) {
      return null;
    }

    accumulator = ((accumulator << frombits) | value) & maxAccumulator;
    bits += frombits;

    while (bits >= tobits) {
      bits -= tobits;
      result.push((accumulator >> bits) & maxValue);
    }
  }

  if (pad) {
    if (bits > 0) {
      result.push((accumulator << (tobits - bits)) & maxValue);
    }
  } else if (bits >= frombits || ((accumulator << (tobits - bits)) & maxValue) !== 0) {
    return null;
  }

  return result;
}

export function decode(hrp, address) {
  const decoded = bech32Decode(address);
  const decodedHrp = decoded[0];
  const data = decoded[1];

  if (decodedHrp !== hrp || data === null) {
    return [null, null];
  }

  const witnessVersion = data[0];
  const witnessProgram = convertbits(data.slice(1), 5, 8, false);

  if (
    witnessProgram === null ||
    witnessProgram.length < 2 ||
    witnessProgram.length > 40 ||
    witnessVersion > 16
  ) {
    return [null, null];
  }

  if (witnessVersion === 0 && witnessProgram.length !== 20 && witnessProgram.length !== 32) {
    return [null, null];
  }

  return [witnessVersion, witnessProgram];
}

export function encode(hrp, witnessVersion, witnessProgram) {
  const converted = convertbits(witnessProgram, 8, 5);
  if (converted === null) {
    return null;
  }

  const result = bech32Encode(hrp, [witnessVersion].concat(converted));
  const decoded = decode(hrp, result);

  if (decoded[0] === null || decoded[1] === null) {
    return null;
  }

  return result;
}

