    super(`invalid literal for int() with base 10: ${formatPythonStringLiteral(rawValue)}`);
    this.name = 'ValueError';
    this.rawValue = rawValue;
  }
}

const PYTHON_INT_PATTERN = /^[+-]?(?:\d(?:_?\d)*)$/;

export function parsePythonInt(rawValue) {
  const trimmed = rawValue.trim();

  if (!PYTHON_INT_PATTERN.test(trimmed)) {
    throw new PythonIntValueError(rawValue);
  }

  return Number(trimmed.replaceAll('_', ''));
}

