import path from 'node:path';

import { parsePythonInt, PythonIntValueError } from './python_int.mjs';
import { formatPythonStringLiteral } from '../format/python.mjs';

const ARGUMENT_DEFINITIONS = [
  { name: 'a', flag: '--a', metavar: 'A', type: 'str' },
  { name: 'b', flag: '--b', metavar: 'B', type: 'int' },
  { name: 'c', flag: '--c', metavar: 'C', type: 'str' },
];

const DEFINITIONS_BY_FLAG = new Map(
  ARGUMENT_DEFINITIONS.map((definition) => [definition.flag, definition]),
);

export class CliExit extends Error {
  constructor(exitCode, stream, text) {
    super(text);
    this.name = 'CliExit';
    this.exitCode = exitCode;
    this.stream = stream;
    this.text = text;
  }
}

function getProgramName(scriptPath) {
  return path.basename(scriptPath || 'test16.mjs');
}

function getUsage(programName) {
  return `usage: ${programName} [-h] --a A --b B --c C`;
}

function getHelp(programName) {
  return `${getUsage(programName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n  --c C\n`;
}

function throwParserError(programName, message) {
  throw new CliExit(2, 'stderr', `${getUsage(programName)}\n${programName}: error: ${message}\n`);
}

function isNegativeNumberToken(token) {
  return /^-\d(?:_?\d)*$/.test(token);
}

function shouldTreatAsMissingValue(nextToken) {
  if (nextToken === undefined) {
    return true;
  }

  if (nextToken === '-') {
    return false;
  }

  if (isNegativeNumberToken(nextToken)) {
    return false;
  }

  return nextToken.startsWith('-');
}

function coerceArgumentValue(definition, rawValue, programName) {
  if (definition.type !== 'int') {
    return rawValue;
  }

  try {
    return parsePythonInt(rawValue);
  } catch (error) {
    if (error instanceof PythonIntValueError) {
      throwParserError(
        programName,
        `argument ${definition.flag}: invalid int value: ${formatPythonStringLiteral(rawValue)}`,
      );
    }

    throw error;
  }
}

export function parseCommandLine(argv, scriptPath) {
  const programName = getProgramName(scriptPath);
  const values = {
    a: undefined,
    b: undefined,
    c: undefined,
  };
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      throw new CliExit(0, 'stdout', getHelp(programName));
    }

    if (token === '--') {
      extras.push(...argv.slice(index + 1));
      break;
    }

    if (token.startsWith('--')) {
      const equalsIndex = token.indexOf('=');
      const flag = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
      const definition = DEFINITIONS_BY_FLAG.get(flag);

      if (definition == null) {
        extras.push(token);
        continue;
      }

      let rawValue;

      if (equalsIndex !== -1) {
        rawValue = token.slice(equalsIndex + 1);
      } else {
        const nextToken = argv[index + 1];

        if (shouldTreatAsMissingValue(nextToken)) {
          throwParserError(programName, `argument ${flag}: expected one argument`);
        }

        rawValue = nextToken;
        index += 1;
      }

      values[definition.name] = coerceArgumentValue(definition, rawValue, programName);
      continue;
    }

    extras.push(token);
  }

  if (extras.length > 0) {
    throwParserError(programName, `unrecognized arguments: ${extras.join(' ')}`);
  }

  const missingFlags = ARGUMENT_DEFINITIONS
    .filter((definition) => values[definition.name] === undefined)
    .map((definition) => definition.flag);

  if (missingFlags.length > 0) {
    throwParserError(
      programName,
      `the following arguments are required: ${missingFlags.join(', ')}`,
    );
  }

  return values;
}

