import { bech32Decode, bech32Encode } from './core.mjs';
import { convertBits } from './convertbits.mjs';

export function decode(hrp, address) {
  const [decodedHrp, data] = bech32Decode(address);

  if (decodedHrp !== hrp) {
    return [null, null];
  }

  const decoded = convertBits(data.slice(1), 5, 8, false);

  if (decoded == null || decoded.length < 2 || decoded.length > 40) {
    return [null, null];
  }

  if (data[0] > 16) {
    return [null, null];
  }

  if (data[0] === 0 && decoded.length !== 20 && decoded.length !== 32) {
    return [null, null];
  }

  return [data[0], decoded];
}

export function encode(hrp, witnessVersion, witnessProgram) {
  const converted = convertBits(witnessProgram, 8, 5);
  const address = bech32Encode(hrp, [witnessVersion, ...converted]);
  const decoded = decode(hrp, address);

  if (decoded[0] === null && decoded[1] === null) {
    return null;
  }

  return address;
}

